import os
import json

from google.cloud import vision_v1

def extract_key_value_pairs_from_form(input_path):
    client = vision_v1.ImageAnnotatorClient()

    with open(input_path, 'rb') as image_file:
        content = image_file.read()

    image = vision_v1.Image(content=content)

    response = client.document_text_detection(image=image)

    document = response.full_text_annotation

    key_value_pairs = {}

    def parse_document(node, parent_key=""):
        if node.property and node.property.key_value:
            key = node.property.key_value.key.text_content.text
            value = node.property.key_value.value.text_content.text
            key_value_pairs[parent_key + key] = value
        else:
            for child in node.layout:
                parse_document(child, parent_key + node.property.key_value.key.text_content.text + "_")

    root = document.pages[0].layout
    parse_document(root)

    return json.dumps(key_value_pairs)
